@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-sr-only,
.teum-sr-only:not(:focus):not(:active) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

.teum-data-table {
  position: relative;
  width: 100%;
  min-width: 0;
  color: var(--teum-fg-default);
}

.teum-data-table > .teum-table__container {
  border-color: color-mix(in oklch, var(--teum-separator) 76%, transparent);
  border-radius: 9px;
  box-shadow: var(--teum-shadow-control);
}

.teum-data-table .teum-table__head,
.teum-data-table .teum-table__cell { padding-inline: 11px; }

.teum-data-table .teum-table__head[data-align="center"],
.teum-data-table .teum-table__cell[data-align="center"] { text-align: center; }

.teum-data-table .teum-table__head[data-align="end"],
.teum-data-table .teum-table__cell[data-align="end"] { text-align: end; }

.teum-data-table__selection-head,
.teum-data-table__selection-cell {
  width: 40px;
  min-width: 40px;
  padding-inline: 11px 0 !important;
}

.teum-data-table__selection-head .teum-choice-row,
.teum-data-table__selection-cell .teum-choice-row { width: 16px; }

.teum-data-table__sort {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  gap: 5px;
  margin-inline: -5px;
  padding: 4px 5px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 560;
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--teum-hover-duration), background-color var(--teum-hover-duration);
}

.teum-data-table__sort > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.teum-data-table__sort svg {
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  color: var(--teum-fg-subtle);
}

.teum-data-table__state {
  height: 240px !important;
  padding: 24px !important;
}

.teum-data-table__state .teum-empty-state { min-height: 190px; }

.teum-data-table__empty-value { color: var(--teum-fg-subtle); }

.teum-data-table__footer {
  display: flex;
  min-height: 45px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 6px 2px 0;
}

.teum-data-table__footer > span {
  color: var(--teum-fg-subtle);
  font-size: var(--teum-type-metadata);
  font-variant-numeric: tabular-nums;
}

.teum-data-table__footer .teum-pagination { margin-left: auto; }

.teum-data-table .teum-table__row[data-activatable] { cursor: default; }

@media (hover: hover) and (pointer: fine) {
.teum-data-table__sort:hover { background: var(--teum-hover); color: var(--teum-fg-default); }
}

@media (max-width: 700px) {
.teum-data-table__footer { align-items: flex-start; flex-direction: column; }

.teum-data-table__footer .teum-pagination { margin-left: 0; }
}
}
